const cfg = {};
for (const item of $input.all()) {
  const key = item.json['Key'] ?? item.json['Kho\u00e1'] ?? item.json['Kh\u00f3a'];
  if (key === undefined || key === null || String(key).trim() === '') continue;
  const value = item.json['Value'] ?? item.json['Gi\u00e1 tr\u1ecb'] ?? '';
  cfg[String(key).trim()] = typeof value === 'string' ? value.trim() : value;
}

const missing = ["SMTP_FROM", "HIEU_TRUONG_EMAIL"].filter((k) => !String(cfg[k] ?? '').trim());
if (missing.length) throw new Error('Config tab thiếu khoá: ' + missing.join(', '));
return [{ json: cfg }];

// Calculate NEXT week Monday date (Thursday/Friday reminder looks at upcoming week)
const now = new Date();
const dayOfWeek = now.getDay(); // 0 is Sun, 4 is Thu, 5 is Fri

// Next Monday is (7 - dayOfWeek + 1) % 7 + (dayOfWeek === 1 ? 7 : 0)
// If today is Thursday (4), days until next Monday = 4 days
// If today is Friday (5), days until next Monday = 3 days
const daysUntilNextMonday = ((1 - dayOfWeek + 7) % 7) || 7;
const nextMonday = new Date(now);
nextMonday.setDate(now.getDate() + daysUntilNextMonday);

// Format DD/MM/YYYY to match Sheet format
const dd = String(nextMonday.getDate()).padStart(2, "0");
const mm = String(nextMonday.getMonth() + 1).padStart(2, "0");
const yyyy = nextMonday.getFullYear();

// Calculate whole working week range (Mon to Fri) for searching
const weekDates = [];
for (let i = 0; i < 5; i++) {
  const d = new Date(nextMonday);
  d.setDate(nextMonday.getDate() + i);
  weekDates.push(
    String(d.getDate()).padStart(2, "0") + "/" +
    String(d.getMonth() + 1).padStart(2, "0") + "/" +
    d.getFullYear()
  );
}

return [{
  json: {
    week_start: `${dd}/${mm}/${yyyy}`,
    week_dates: weekDates,
    check_type: dayOfWeek === 5 ? "friday_escalation" : "thursday_reminder"
  }
}];

// Check if this week's menu entries exist and have content
const weekDates = $('Calculate Week Dates').first().json.week_dates;
const allRows = $input.all().map(item => item.json);

const missingDays = [];
const filledDays = [];

for (const date of weekDates) {
  const row = allRows.find(r => r['Ngày'] === date);
  if (!row || !row['Nội dung'] || row['Nội dung'].toString().trim() === '') {
    missingDays.push(date);
  } else {
    filledDays.push(date);
  }
}

return [{
  json: {
    has_missing: missingDays.length > 0,
    missing_days: missingDays,
    filled_days: filledDays,
    missing_count: missingDays.length,
    total_days: weekDates.length,
    summary: missingDays.length > 0
      ? `Thiếu thực đơn cho ${missingDays.length}/${weekDates.length} ngày: ${missingDays.join(', ')}`
      : `Đã có đủ thực đơn cho cả tuần (${weekDates.length} ngày)`
  }
}];

// Re-check after waiting — same logic as Thursday check
const weekDates = $('Calculate Week Dates').first().json.week_dates;
const allRows = $input.all().map(item => item.json);

const stillMissing = [];
for (const date of weekDates) {
  const row = allRows.find(r => r['Ngày'] === date);
  if (!row || !row['Nội dung'] || row['Nội dung'].toString().trim() === '') {
    stillMissing.push(date);
  }
}

return [{
  json: {
    still_missing: stillMissing.length > 0,
    missing_days: stillMissing,
    missing_count: stillMissing.length
  }
}];

// ---- shared helpers (same block in every multi-tab Code node) ----
const noAcc = (s) => String(s ?? '').normalize('NFC').replace(/đ/g, 'd').replace(/Đ/g, 'D')
  .normalize('NFD').replace(/[̀-ͯ]/g, '').normalize('NFC');
const low = (s) => noAcc(s).toLowerCase().trim();
const truthy = (v) => v === true || ['TRUE', 'CO', 'X', '1'].includes(noAcc(v).trim().toUpperCase());
const TAB_CODES = { 'thuc don': 'td', 'thong bao': 'tb', 'lich/tkb': 'lich', 'lich': 'lich', 'tin hoat dong': 'tin' };
const TAB_EMOJI = { td: '🍽️', tb: '📢', lich: '📅', tin: '🌟' };
const tabCode = (tab) => TAB_CODES[low(tab)] || low(tab).replace(/[^a-z0-9]+/g, '');
const parseTabs = (v) => String(v || 'Thực đơn').split(',').map((t) => t.trim()).filter(Boolean);
const colLetter = (i) => { let s = ''; for (let n = i + 1; n > 0; n = Math.floor((n - 1) / 26)) s = String.fromCharCode(65 + ((n - 1) % 26)) + s; return s; };
const qTab = (tab) => `'${String(tab).replace(/'/g, "''")}'`;
const batchQuery = (tabs) => tabs.map((t) => 'ranges=' + encodeURIComponent(`${qTab(t)}!A1:Z`)).join('&');
// valueRange -> { cols: {header: letter}, rows: [{...header: value, row_number}] }
const readTab = (vr) => {
  const values = (vr && vr.values) || [];
  const header = (values[0] || []).map((h) => String(h ?? '').trim());
  const cols = {};
  header.forEach((h, i) => { if (h) cols[h] = colLetter(i); });
  const rows = values.slice(1).map((r, i) => {
    const o = { row_number: i + 2 };
    header.forEach((h, j) => { if (h) o[h] = r[j] ?? ''; });
    return o;
  });
  return { cols, rows };
};
const cell = (tab, cols, header, row) => {
  if (!cols[header]) throw new Error(`Tab "${tab}" thiếu cột "${header}"`);
  return `${qTab(tab)}!${cols[header]}${row}`;
};
const PHONE = /(?:\+?84|0)(?:\d[\s.-]?){8,10}\d/;
const nowVN = () => new Date().toLocaleString('en-GB', { timeZone: 'Asia/Ho_Chi_Minh', hour12: false }).replace(',', '');
const todayVN = () => new Date().toLocaleDateString('en-GB', { timeZone: 'Asia/Ho_Chi_Minh' });
// ---- end shared helpers ----

// One reminder per responsible person, on the channel they chose in tab "Nhân sự".
const active = (v) => !['false', 'khong', 'no', '0', 'ngung'].includes(low(v));
const check = $('Check Missing Menus').first().json;
const cfg = $('Read Config').first().json;
const out = [], skipped = [];
for (const { json: j } of $('Đọc Nhân sự').all()) {
  const name = String(j['Họ tên'] ?? '').trim();
  if (!name || !active(j['Đang dùng'])) continue;
  if (!low(j['Vai trò']).includes('nhap')) continue;
  const kinds = String(j['Loại nội dung'] ?? '').split(',').map((s) => tabCode(s)).filter(Boolean);
  if (kinds.length && !kinds.includes('td')) continue;
  if (['khong', 'no', 'false', '0'].includes(low(j['Nhắc việc']))) continue;
  const email = String(j['Email'] ?? '').trim();
  const chat = String(j['Zalo chat ID'] || j['Zalo ID'] || '').trim();
  const k = low(j['Kênh nhận']);
  const channels = k.includes('ca hai') ? ['email', 'zalo'] : k.includes('zalo') ? ['zalo'] : k.includes('email') ? ['email'] : [email ? 'email' : 'zalo'];
  const text = `Chào ${name},\n${check.summary}.\nNgày còn thiếu: ${check.missing_days.join(', ')}.\nVui lòng nhập thực đơn vào bảng tính (hoặc nhắn bot: thực đơn dd/mm: ...) trước cuối ngày hôm nay.`;
  for (const ch of channels) {
    if (ch === 'email' && email) out.push({ json: { channel: 'email', to: email, name, text, summary: check.summary, missing_days: check.missing_days } });
    else if (ch === 'zalo' && chat) out.push({ json: { channel: 'zalo', chat_id: chat, name, text } });
    else skipped.push(`${name} (${ch})`);
  }
}
if (!out.length) {
  if (!String(cfg.BAN_TRU_EMAIL || '').trim()) throw new Error('Không có người nhận nhắc thực đơn: thêm người ở tab Nhân sự hoặc BAN_TRU_EMAIL ở Config');
  out.push({ json: { channel: 'email', to: String(cfg.BAN_TRU_EMAIL).trim(), name: 'bộ phận bán trú', text: '', summary: check.summary, missing_days: check.missing_days } });
}
// People with no usable address are listed on every item so the run shows them.
return out.map((o) => ({ json: { ...o.json, skipped } }));
